### The Master Dual-Peripheral Sketch

Upload this complete, working sketch to your Arduino Uno. It coordinates both the DS3231 RTC (`comp_10`) and 16x2 LCD (`comp_07`) over the shared bus without external clock libraries:

```cpp
#include <Wire.h>
#include <LiquidCrystal_I2C.h>

const byte LCD_ADDR   = 0x27;
const byte DS3231_ADDR = 0x68;

LiquidCrystal_I2C lcd(LCD_ADDR, 16, 2);

unsigned long lastTick = 0;
const unsigned long TICK_INTERVAL = 1000; // Update once per second

// Convert BCD to Decimal integer
byte bcdToDec(byte bcd) {
  return ((bcd >> 4) * 10) + (bcd & 0x0F);
}

void setup() {
  Wire.begin();
  Serial.begin(9600);

  lcd.init();
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print("MONSTER LAB RTC");
  lcd.setCursor(0, 1);
  lcd.print("INITIALIZING...");
  delay(1000);
  lcd.clear();
}

void loop() {
  // Non-blocking 1-second cadence
  if (millis() - lastTick >= TICK_INTERVAL) {
    lastTick = millis();

    // 1. Read Time from DS3231 (0x68)
    Wire.beginTransmission(DS3231_ADDR);
    Wire.write(0x00); // Point to register 0x00 (Seconds)
    Wire.endTransmission();

    Wire.requestFrom(DS3231_ADDR, (byte)7);
    if (Wire.available() >= 7) {
      byte sec  = bcdToDec(Wire.read() & 0x7F);
      byte min  = bcdToDec(Wire.read());
      byte hr   = bcdToDec(Wire.read() & 0x3F);
      Wire.read(); // Skip day of week
      byte date = bcdToDec(Wire.read());
      byte mon  = bcdToDec(Wire.read() & 0x1F);
      byte yr   = bcdToDec(Wire.read());

      // 2. Read Temperature Registers (0x11 and 0x12)
      Wire.beginTransmission(DS3231_ADDR);
      Wire.write(0x11);
      Wire.endTransmission();
      Wire.requestFrom(DS3231_ADDR, (byte)2);
      int tempMSB = Wire.read();
      int tempLSB = Wire.read() >> 6; // Upper 2 bits = fractional 0.25 C
      float tempC = tempMSB + (tempLSB * 0.25);

      // 3. Render Line 1: TIME [HH:MM:SS]
      lcd.setCursor(0, 0);
      lcd.print("TIME: ");
      if (hr < 10) lcd.print('0');
      lcd.print(hr);
      lcd.print(':');
      if (min < 10) lcd.print('0');
      lcd.print(min);
      lcd.print(':');
      if (sec < 10) lcd.print('0');
      lcd.print(sec);

      // 4. Render Line 2: DATE & TEMP [DD/MM  24.5C]
      lcd.setCursor(0, 1);
      if (date < 10) lcd.print('0');
      lcd.print(date);
      lcd.print('/');
      if (mon < 10) lcd.print('0');
      lcd.print(mon);
      lcd.print("  ");
      lcd.print(tempC, 1);
      lcd.print((char)223); // Degree symbol in HD44780 font ROM
      lcd.print('C');
    }
  }
}
```

### Code Deconstruction:
- `(char)223`: Character code `223` in the LCD controller's internal ROM represents the degree symbol (`°`).
- `lcd.setCursor(0, 0)`: Places the writing cursor at the top-left coordinate, completely avoiding `lcd.clear()` and eliminating screen flicker.
- `Wire.requestFrom(DS3231_ADDR, 2)`: Demonstrates reading internal TCXO temperature registers `0x11` and `0x12` seamlessly during the same loop iteration.

